const raw = (($json.target) || '').trim().toLowerCase();
const authorized = $json.authorized === true || $json.authorized === 'true';
const hostnameRe = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)*$/;
const ipv4Re = /^(\d{1,3}\.){3}\d{1,3}$/;
const ipv6Re = /^[0-9a-f:]+$/i;
const cidrRe = /^(\d{1,3}\.){3}\d{1,3}\/(\d{1,2})$/;
const cidrMatch = raw.match(cidrRe);
let isCidr = false, blocked = null;
if (cidrMatch) {
  const prefix = Number(cidrMatch[2]);
  if (!authorized) { blocked = 'authorization checkbox not confirmed'; }
  else if (prefix < 24) { blocked = `CIDR range too large (/${prefix} - this tool bounds network sweeps to /24 or smaller, max 256 addresses)`; }
  else { isCidr = true; }
  return [{ json: { target: raw, isIp: false, isCidr, scanIntensity: $json.scanIntensity || 'dns-only', blocked } }];
}
const isIp = ipv4Re.test(raw) || (raw.includes(':') && ipv6Re.test(raw));
const valid = raw.length > 0 && raw.length < 254 && (isIp || hostnameRe.test(raw));
blocked = !authorized ? 'authorization checkbox not confirmed' : (!valid ? 'target failed validation' : null);
return [{ json: { target: raw, isIp, isCidr: false, scanIntensity: $json.scanIntensity || 'dns-only', blocked } }];

const norm = $('Validate & Normalize').item.json;
const recon = $('Recon Target').item.json;
const xml = $json.stdout || '';
const hostBlockRe = /<host>([\s\S]*?)<\/host>/g;
const hosts = [];
let hm;
while ((hm = hostBlockRe.exec(xml)) !== null) {
  const block = hm[1];
  if (!/<status state="up"/.test(block)) continue;
  const addrMatch = block.match(/<address addr="([\d.]+)" addrtype="ipv4"/);
  if (addrMatch) hosts.push(addrMatch[1]);
}
const prefixMatch = norm.target.match(/\/(\d{1,2})$/);
const prefix = prefixMatch ? Number(prefixMatch[1]) : 24;
const totalInRange = Math.pow(2, 32 - prefix);
const ratio = totalInRange > 0 ? hosts.length / totalInRange : 0;

if (hosts.length === 0) {
  return [{ json: { noHostsFound: true, cidr: norm.target, hostsDiscovered: 0, totalInRange } }];
}
if (ratio > 0.5) {
  return [{ json: { unroutable: true, cidr: norm.target, hostsDiscovered: hosts.length, totalInRange } }];
}
const capped = hosts.slice(0, 20);
return capped.map((ip) => ({ json: {
  target: ip, isIp: true, scanIntensity: norm.scanIntensity,
  sqlInjectionTest: recon.sqlInjectionTest, webVulnScan: recon.webVulnScan,
  __cidr: norm.target, __hostsDiscovered: hosts.length, __hostsScanned: capped.length,
} }));

const items = $input.all();
const norm = $('Validate & Normalize').item.json;
const now = new Date();
const stamp = now.toISOString().replace(/[-:T]/g,'').slice(0,15).replace(/(\d{8})(\d{6})/, '$1-$2');
let rows = items.map(it => {
  const j = it.json;
  const t = j.target || (j.__cidr ? j.__cidr : 'unknown');
  return `| ${t} | see recon/${t}-*.md |`;
}).join('\n');
const summaryContent = `# Network Sweep Summary: ${norm.target}\n\n- Timestamp: ${stamp}\n- Hosts discovered: ${items[0]?.json?.__hostsDiscovered ?? 0}\n- Hosts scanned: ${items.length}\n\n| Host | Report |\n|---|---|\n${rows}\n`;
return [{ json: { summaryContent, summaryFilename: `network-sweep-${norm.target.replace(/\//g,'_')}-${stamp}.md` } }];

const items = $input.all();
const norm = $('Validate & Normalize').item.json;
const item = items[0]?.json || {};
const now = new Date();
const stamp = now.toISOString().replace(/[-:T]/g,'').slice(0,15).replace(/(\d{8})(\d{6})/, '$1-$2');
let reason;
if (item.unroutable) {
  reason = `${item.hostsDiscovered} of ${item.totalInRange} addresses in ${norm.target} reported "up" during host discovery. That is an implausibly high live-host ratio for any real network and matches this platform's known NAT limitation: the scanning container has no real route to this range, and the podman/gvproxy NAT layer fabricates connection-refused responses for unroutable destinations rather than timing out. Treating this range as unroutable from the current scanning platform rather than reporting fabricated per-host findings.`;
} else {
  reason = `0 of ${item.totalInRange || '?'} addresses in ${norm.target} responded to host discovery. Either the range is genuinely empty/down, or (as with other private ranges on this platform) it is not reachable from the scanning container at all. No per-host recon was dispatched.`;
}
const summaryContent = `# Network Sweep Summary: ${norm.target}\n\n- Timestamp: ${stamp}\n- Status: unroutable\n\n${reason}\n`;
return [{ json: { summaryContent, summaryFilename: `network-sweep-${norm.target.replace(/\//g,'_')}-${stamp}.md` } }];

